typedef struct { char *data; size_t len, cap; } strbuf;

void collect_token(strbuf *out, const char *tok) {
    sb_addf(out, "[%s]", tok);          /* appends into the caller's buffer */
}

int main(void) {
    strbuf out = {0};
    for (size_t i = 0; i < ntok; i++) collect_token(&out, tokens[i]);
    puts(out.data);
    sb_free(&out);
}
